import{_ as n,a0 as l,w as p,s as h,ao as u,I as r,x as e,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const W=JSON.parse('{"title":"如何在 Ubuntu 22.04 中安装和使用 Wireshark | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 22.04 中安装和使用 Wireshark | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 22.04 中安装和使用 Wireshark | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 22.04 中安装和使用 Wireshark | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230624.0 ⭐️⭐️ How to Install and Use Wireshark in Ubuntu 22.04","title":"如何在 Ubuntu 22.04 中安装和使用 Wireshark","tag":"202307","desc":""},"relativePath":"202307/20230624.0 ⭐️⭐️ How to Install and Use Wireshark in Ubuntu 22.04.md","filePath":"[post].md"}'),o={name:"202307/20230624.0 ⭐️⭐️ How to Install and Use Wireshark in Ubuntu 22.04.md"};function d(k,s,c,b,g,w){const a=l("Link");return p(),h("div",null,[s[15]||(s[15]=u(`<h1 id="如何在-ubuntu-22-04-中安装和使用-wireshark" tabindex="-1">如何在 Ubuntu 22.04 中安装和使用 Wireshark <a class="header-anchor" href="#如何在-ubuntu-22-04-中安装和使用-wireshark" aria-label="Permalink to “如何在 Ubuntu 22.04 中安装和使用 Wireshark”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/05/154817pj3jx0jl03levzu9.jpg" alt=""></p><blockquote><p>技术兄弟们，大家好，在这篇文章中我们将介绍如何在 Ubuntu 22.04 中安装和使用 Wireshark。</p></blockquote><p>Wireshark 是自由开源的、跨平台的、基于 GUI 的网络数据包分析器，可用于 Linux、Windows、MacOS、Solaris 等。它实时捕获网络数据包并以人类可读的格式呈现它们。它使我们能够监控微观层面的网络数据包。它还有一个名为 <code>tshark</code> 的命令行程序，它执行与 Wireshark 相同的功能，但通过终端而不是通过 GUI。</p><p>Wireshark 可用于网络故障排除、分析、软件和通信协议开发，也可用于教育目的。Wireshark 使用名为 <code>pcap</code> 的库来捕获网络数据包。</p><h3 id="wireshark-的功能" tabindex="-1">Wireshark 的功能 <a class="header-anchor" href="#wireshark-的功能" aria-label="Permalink to “Wireshark 的功能”">​</a></h3><ul><li>支持检查数百种协议</li><li>能够实时捕获数据包并保存它们以供以后离线分析</li><li>一些用于分析数据的过滤器</li><li>捕获的数据可以动态压缩和解压缩</li><li>支持多种数据分析文件格式，输出也可以保存为 XML、CSV、纯文本格式</li><li>可以从以太网、WiFi、蓝牙、USB、帧中继、令牌环等多种接口捕获数据</li></ul><h3 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to “先决条件”">​</a></h3><ul><li>预装 Ubuntu 22.04</li><li>具有 sudo 权限的本地用户</li><li>互联网连接</li></ul><h3 id="wireshark-安装步骤" tabindex="-1">Wireshark 安装步骤 <a class="header-anchor" href="#wireshark-安装步骤" aria-label="Permalink to “Wireshark 安装步骤”">​</a></h3><h4 id="从-ubuntu-仓库安装" tabindex="-1">从 Ubuntu 仓库安装 <a class="header-anchor" href="#从-ubuntu-仓库安装" aria-label="Permalink to “从 Ubuntu 仓库安装”">​</a></h4><p>Wireshark 包可在默认的 Ubuntu 仓库中找到，并且可以使用以下命令简单地安装。但你可能无法获得最新版本的 wireshark。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span>
<span class="line"><span>$ sudo apt install wireshark</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Apt-Command-Install-Wireshark-Ubuntu.png" alt="Apt-Command-Install-Wireshark-Ubuntu"></p><p>选择 “Yes” 允许非超级用户使用 Wireshark 捕获数据包：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Allow-Non-SuperUsers-To-Capture-Packets-Wireshark-Ubuntu.png" alt="Allow-Non-SuperUsers-To-Capture-Packets-Wireshark-Ubuntu"></p><p>安装成功后，访问 Wireshare UI。从“<ruby>活动<rt>Activities</rt></ruby>”中搜索 “wireshark”，然后单击其图标。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Wireshark-UI-Ubuntu-Linux-Desktop.png" alt="Wireshark-UI-Ubuntu-Linux-Desktop"></p><p>以上确认你的 Wireshark 安装已成功完成。</p><h4 id="安装最新的版本" tabindex="-1">安装最新的版本 <a class="header-anchor" href="#安装最新的版本" aria-label="Permalink to “安装最新的版本”">​</a></h4><p>如果要安装最新版本的 Wireshark，我们必须使用以下 <code>apt</code> 命令启用官方 Wireshark 仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo add-apt-repository ppa:wireshark-dev/stable</span></span>
<span class="line"><span>$ sudo apt update</span></span></code></pre></div><p>现在，安装最新版本的 Wireshark，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install wireshark -y</span></span></code></pre></div><p>安装 Wireshark 后，验证其版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wireshark --version</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Wireshark-Version-Check-Ubuntu-Linux.png" alt="Wireshark-Version-Check-Ubuntu-Linux"></p><p>要允许普通用户使用 Wireshark 使用和捕获数据包，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dpkg-reconfigure wireshark-common</span></span></code></pre></div><p>选择 “Yes” 并按回车键。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Allow-Regular-User-Use-Wireshark-Ubuntu.png" alt="Allow-Regular-User-Use-Wireshark-Ubuntu"></p><p>使用 <code>usermod</code> 命令将本地用户添加到 <code>wireshark</code> 组:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -aG wireshark $USER</span></span>
<span class="line"><span>$ newgrp wireshark</span></span></code></pre></div><p>要使上述更改生效，请重新启动系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo reboot</span></span></code></pre></div><h3 id="使用-wireshark-捕获数据包" tabindex="-1">使用 Wireshark 捕获数据包 <a class="header-anchor" href="#使用-wireshark-捕获数据包" aria-label="Permalink to “使用 Wireshark 捕获数据包”">​</a></h3><p>启动 Wireshark，从“活动”-&gt;搜索 “wireshark”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Access-Wireshark-Ubuntu-Desktop.png" alt="Access-Wireshark-Ubuntu-Desktop"></p><p>单击 Wireshark 图标，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Choose-Interface-Wireshark-UI-Ubuntu.png" alt="Choose-Interface-Wireshark-UI-Ubuntu"></p><p>所有这些都是我们可以捕获网络数据包的接口。根据你系统上的界面，此页面可能会有所不同。</p><p>我们选择 “enp0s3” 来捕获该接口的网络流量。选择接口后，我们网络上所有设备的网络数据包开始填充（请参阅下面的截图）：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Capturing-Packets-WireShark-UI-Ubuntu.png" alt="Capturing-Packets-WireShark-UI-Ubuntu"></p><p>第一次看到此页面时，我们可能会被此屏幕中显示的数据淹没，并且可能会想到如何整理这些数据，但不用担心，Wireshark 的最佳功能之一就是它的过滤器。</p><p>我们可以根据 IP 地址、端口号对数据进行排序/过滤，还可以使用源和目标过滤器、数据包大小等，还可以将 2 个或更多过滤器组合在一起以创建更全面的搜索。我们可以在“<ruby>应用显示过滤器<rt>Apply a Display Filter</rt></ruby>”选项卡中编写过滤器，也可以选择已创建的规则之一。要选择预建过滤器，请单击“旗帜”图标，然后点击“应用显示过滤器”选项卡。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/IP-Based-Filtering-WireShark-UI-Ubuntu.png" alt="IP-Based-Filtering-WireShark-UI-Ubuntu"></p><p>我们还可以根据颜色代码来过滤数据，默认情况下，浅紫色是 TCP 流量，浅蓝色是 UDP 流量，黑色标识有错误的数据包，要查看这些代码的含义，请单击“<ruby>查看<rt>View</rt></ruby>”-&gt;“<ruby>颜色规则<rt>Coloring Rules</rt></ruby>”，我们也可以更改这些代码。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Coloring-Rules-WireShark-Ubuntu.png" alt="Coloring-Rules-WireShark-Ubuntu"></p><p>获得所需的结果后，我们可以单击任何捕获的数据包以获取有关该数据包的更多详细信息，这将显示有关该网络数据包的所有数据。</p><p>要停止捕获数据包，请单击红色停止按钮，然后将捕获的数据包保存到文件中。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Save-Captured-Packets-Wireshark-Ubuntu.png" alt="Save-Captured-Packets-Wireshark-Ubuntu"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>Wireshark 是一款非常强大的工具，需要一些时间来适应和掌握它，这篇文章将帮助你开始使用。请随时在下面的评论栏中提出你的疑问或建议。</p><p><em>（题图：MJ/63c09e75-a3e7-4dbf-ac6f-0233bdd34ad8）</em></p><hr>`,55)),r("p",null,[s[1]||(s[1]=e("via: ",-1)),i(a,{href:"https://www.linuxtechi.com/install-use-wireshark-ubuntu/"},{default:t(()=>[...s[0]||(s[0]=[e("https://www.linuxtechi.com/install-use-wireshark-ubuntu/",-1)])]),_:1})]),r("p",null,[s[6]||(s[6]=e("作者：",-1)),i(a,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...s[2]||(s[2]=[e("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),i(a,{href:"https://github.com/lkxed/"},{default:t(()=>[...s[3]||(s[3]=[e("lkxed",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),r("p",null,[s[12]||(s[12]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const f=n(o,[["render",d]]);export{W as __pageData,f as default};
